const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
const KEY='present.cusat.v1', DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
let state={profile:null,subjects:[],slots:[],records:{},extras:[],target:75}, step=0, view='today', date=today(), day=1, draft={name:'',college:'',programme:'B.Tech',department:'',year:'',semester:'1'}, pending=[];
try{const raw=localStorage.getItem(KEY);if(raw){const s=JSON.parse(raw);if(s.profile&&Array.isArray(s.subjects)&&Array.isArray(s.slots))state=s;}}catch{}
let storageError=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageError=false;}catch{storageError=true;toast('Storage is unavailable. Export a backup before closing.');}}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
const brand='<div class="brand"><span class="brandmark">↗</span>present<span style="color:var(--accent)">.</span></div>';
const icons={today:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18m-13 5h3"/>',subjects:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-3-2H4zm16 0h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 3-2h4z"/>',timetable:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 9v12M15 9v12"/>',settings:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>'};
const opt=(arr,val)=>arr.map(x=>`<option ${String(val)===String(x)?'selected':''}>${esc(x)}</option>`).join('');
function profileFields(p){return `<div class="fields"><label>What should we call you?<input name="name" placeholder="Your first name" autocomplete="given-name" maxlength="40" required value="${esc(p.name)}"></label><label>College / campus<input name="college" placeholder="e.g. School of Engineering, CUSAT" maxlength="80" required value="${esc(p.college)}" list="colleges"><datalist id="colleges"><option>School of Engineering, CUSAT</option><option>CUCEK, Kuttanad</option><option>CUSAT, Main Campus</option><option>CUSAT, Lakeside Campus</option></datalist></label><div class="row"><label>Programme<select name="programme">${opt(['B.Tech','M.Tech','B.Sc','M.Sc','Integrated M.Sc','MBA','MCA','LLB','Other'],p.programme)}</select></label><label>Department<input name="department" placeholder="e.g. Computer Science" maxlength="80" required value="${esc(p.department)}"></label></div><div class="row"><label>Admission year<input type="number" name="year" min="2000" max="${new Date().getFullYear()+1}" placeholder="e.g. ${new Date().getFullYear()}" required value="${esc(p.year)}"></label><label>Current semester<select name="semester">${opt(Array.from({length:12},(_,i)=>i+1),p.semester)}</select></label></div></div>`}
function onboarding(){app.innerHTML=`<header class="top">${brand}<span class="tag">MADE FOR CAMPUS LIFE</span></header><main class="onboard"><aside class="intro"><div class="eyebrow muted">A LITTLE LESS GUESSWORK</div><h1>Make every<br>class <em>count.</em></h1><p class="muted">Your timetable, your attendance, and a clearer picture of where you stand.</p><div class="art" aria-label="Illustration of an attendance summary"><div class="mini"><div class="minihead"><span>YOUR SEMESTER</span><span style="color:var(--green)">↗ On track</span></div><div class="mininumber">86.4<span>%</span></div><div class="bar"><i style="width:86.4%"></i></div><small>More clarity. Less last-minute maths.</small></div><div class="sticker">✓ &nbsp; Room to breathe.</div></div><div class="introfoot"><i>✓</i><span>A small habit. A calmer semester.</span></div></aside><section class="setup"><div class="steps" aria-label="Step ${step+1} of 3">${[0,1,2].map(i=>`<span class="step ${i<=step?'active':''}"></span>`).join('')}</div><div class="fade"><div class="eyebrow steptext">0${step+1} / 03 &nbsp; ${['THE INTRODUCTION','YOUR CLASSES','YOUR PACE'][step]}</div>${step===0?`<h2>First, a little about you.</h2><p class="subtitle muted">Let’s make this feel like your semester.<br>You can always change these later.</p><form id="profileform">${profileFields(draft)}<div class="actions"><button class="primary wide" type="submit">Continue <span>→</span></button></div><p class="disclaimer">No account needed. Your details stay in this browser.</p></form>`:step===1?`<h2>What’s on your plate?</h2><p class="subtitle muted">Add the subjects you’re taking this semester. Your timetable comes next, once you’re in.</p><form id="subjectform"><label>Subject name<div class="addline"><input name="subject" placeholder="e.g. Engineering Mathematics" maxlength="80" required><button type="submit" aria-label="Add subject">+</button></div></label></form><div id="pending">${pending.map((s,i)=>`<div class="subjectitem"><span class="subjectglyph">${String(i+1).padStart(2,'0')}</span><div>${esc(s.name)}</div><button class="iconbtn" data-remove="${i}" aria-label="Remove ${esc(s.name)}">×</button></div>`).join('')}</div>${!pending.length?'<p class="disclaimer">Start with one subject. Add the rest whenever you like.</p>':''}<div class="actions"><button class="textbtn" id="back">← Back</button><button class="primary" id="next" ${!pending.length?'disabled':''}>Continue <span>→</span></button></div>`:`<h2>A little breathing room.</h2><p class="subtitle muted">Choose the attendance percentage you want to stay above.</p><form id="targetform"><label>Your attendance target<select name="target">${opt([75,80,85,90,95],75)}</select><small>75% is a starting target, not a verified rule for your batch.</small></label><div class="note"><strong>Already halfway through the semester?</strong><br>Add your existing attended and held counts under Subjects. Until then, your totals reflect only what you record here.</div><p class="disclaimer">CUSAT rules vary by programme and admission year. Confirm your applicable requirement with your department. This app doesn’t grant condonation or confirm exam eligibility.</p><div class="actions"><button type="button" class="textbtn" id="back">← Back</button><button class="primary orange" type="submit">Let’s begin <span>→</span></button></div></form>`}</div></section></main><footer class="bottom"><span>Built around your everyday.</span><span>PERSONAL ATTENDANCE COMPANION · CUSAT</span></footer>`;
if(step===0)$('#profileform').onsubmit=e=>{e.preventDefault();draft=Object.fromEntries(new FormData(e.target));if(!draft.name.trim()||!draft.department.trim()||!draft.college.trim())return;step=1;onboarding()};
if(step===1){$('#subjectform').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('subject').trim();if(!name)return;if(pending.some(s=>s.name.toLowerCase()===name.toLowerCase()))return toast('That subject is already on your list.');pending.push({id:uid(),name,attended:0,held:0});onboarding();$('input[name=subject]').focus()};document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{pending.splice(+b.dataset.remove,1);onboarding()});$('#next').onclick=()=>{step=2;onboarding()}}
if(step>0)$('#back').onclick=()=>{step--;onboarding()};if(step===2)$('#targetform').onsubmit=e=>{e.preventDefault();state.profile=draft;state.subjects=pending;state.target=+new FormData(e.target).get('target');save();render();toast('You’re all set. Make yourself at home.')};}
function counts(id){let a=0,h=0;state.subjects.filter(s=>!id||s.id===id).forEach(s=>{a+=Number(s.attended)||0;h+=Number(s.held)||0});Object.values(state.records).filter(r=>!id||r.subject===id).forEach(r=>{if(r.status==='present'){a++;h++}if(r.status==='absent')h++});return {a,h,p:h?a/h*100:null}}
function forecast(c){if(!c.h)return 'Record a class to see your forecast.';const t=state.target/100;if(c.a/c.h<t){const n=Math.max(0,Math.ceil((t*c.h-c.a)/(1-t)-1e-9));return `Attend the next ${n} ${n===1?'class':'classes'} to reach ${state.target}%.`}const n=Math.max(0,Math.floor(c.a/t-c.h+1e-9));return `You can miss ${n} ${n===1?'class':'classes'} and stay at ${state.target}%.`}
function sessions(){const w=new Date(date+'T12:00:00').getDay();return [...state.slots.filter(s=>s.day===w&&s.start<=date).map(s=>({...s,key:date+'_'+s.id})),...state.extras.filter(s=>s.date===date).map(s=>({...s,key:date+'_'+s.id}))].sort((a,b)=>a.time.localeCompare(b.time))}
function render(){if(!state.profile)return onboarding();const p=state.profile;app.innerHTML=`<div class="shell"><aside class="sidebar">${brand}<nav class="nav" aria-label="Main navigation">${Object.entries({today:'Today',subjects:'Subjects',timetable:'Timetable',settings:'Profile'}).map(([k,v])=>`<button data-nav="${k}" class="${view===k?'active':''}" ${view===k?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true">${icons[k]}</svg>${v}</button>`).join('')}</nav><div class="sidefoot"><div class="identity"><div class="avatar">${esc(p.name.slice(0,1).toUpperCase())}</div><div>${esc(p.name)}<small>Semester ${esc(p.semester)} · ${esc(p.programme)}</small></div></div></div></aside><main class="main"><div class="utility"><span class="eyebrow">YOUR CAMPUS COMPANION</span><span class="mobilebrand">${brand}</span><span class="localdot">${storageError?'Not saved — export backup':'Saved on this device'}</span></div><div id="content" class="fade"></div></main></div>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;render()});({today:renderToday,subjects:renderSubjects,timetable:renderTimetable,settings:renderSettings}[view])()}
function renderToday(){const c=counts(),s=sessions(),recorded=s.filter(x=>state.records[x.key]).length;$('#content').innerHTML=`<header class="pagehead"><div><h1>A little clarity, ${esc(state.profile.name)}.</h1><p class="muted">One class at a time. Here’s where you stand.</p></div></header><section class="summary" aria-label="Attendance summary"><div class="stat"><div class="eyebrow">OVERALL ATTENDANCE</div><div class="number">${c.p===null?'—':c.p.toFixed(1)}<span>%</span></div><p>${c.h?`${c.a} attended / ${c.h} recorded periods`:'Your semester starts with the first record.'}</p></div><div class="stat"><div class="eyebrow">YOUR TARGET</div><div class="number">${state.target}<span>%</span></div><p>${forecast(c)}</p></div><div class="stat"><div class="eyebrow">SELECTED DAY</div><div class="number">${recorded}<span> / ${s.length}</span></div><p>${s.length?'classes marked. Keep the small habit going.':'No classes scheduled. Add your timetable below.'}</p></div></section><div class="sectionhead"><h2>Your classes</h2><div class="datecontrol"><button class="iconbtn" id="prevdate" aria-label="Previous day">‹</button><input type="date" id="date" aria-label="Attendance date" max="${today()}" value="${date}"><button class="iconbtn" id="nextdate" aria-label="Next day" ${date>=today()?'disabled':''}>›</button></div></div>${s.length?s.map(x=>classRow(x,true)).join(''):`<div class="empty"><h3>A little space in your day.</h3><p>No classes scheduled for ${DAYS[new Date(date+'T12:00:00').getDay()]}.<br>Add a one-off class, or set up your weekly timetable.</p><button class="primary" id="setupweek">Set up timetable <span>→</span></button></div>`}<button class="textbtn" id="addclass" style="margin-top:18px">+ Add a class for this day</button><p class="disclaimer">Self-recorded attendance · Cancelled and unmarked classes don’t affect your totals.<br>Overall attendance uses total periods, not an average of subject percentages.</p>`;$('#date').onchange=e=>{if(!e.target.value||e.target.value>today())return;date=e.target.value;render()};const move=n=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);date=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;render()};$('#prevdate').onclick=()=>move(-1);$('#nextdate').onclick=()=>move(1);if($('#setupweek'))$('#setupweek').onclick=()=>{view='timetable';render()};$('#addclass').onclick=()=>sessionDialog(false);bindMarks()}
function classRow(s,mark){const subj=state.subjects.find(x=>x.id===s.subject),status=state.records[s.key]?.status;return `<article class="classrow"><time>${esc(s.time)}<small>1 period</small></time><div class="classinfo"><span class="subjectglyph">${esc((subj?.name||'?').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase())}</span><div><h3>${esc(subj?.name||'Removed subject')}</h3><small>${mark?(status?status[0].toUpperCase()+status.slice(1):'Waiting to be marked'):'Every '+DAYS[s.day]+' · From '+s.start}</small></div></div>${mark?`<div class="marking">${['present','absent','cancelled'].map(k=>`<button data-key="${s.key}" data-subject="${s.subject}" data-mark="${k}" class="${status===k?'selected':''}" aria-pressed="${status===k}">${k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div>`:`<button class="iconbtn" data-delete-slot="${s.id}" aria-label="Remove this timetable period">×</button>`}</article>`}
function bindMarks(){document.querySelectorAll('[data-mark]').forEach(b=>b.onclick=()=>{const {key,subject,mark}=b.dataset;if(state.records[key]?.status===mark)delete state.records[key];else state.records[key]={subject,status:mark,date};save();render()})}
function renderSubjects(){$('#content').innerHTML=`<header class="pagehead"><div><h1>The bigger picture.</h1><p class="muted">Every subject, with room to plan ahead.</p></div><button class="primary" id="addsubject">+ Add subject</button></header><div class="subjectgrid">${state.subjects.map(s=>{const c=counts(s.id);return `<article class="subjectcard"><div class="cardtitle"><h3>${esc(s.name)}</h3><span class="eyebrow muted">${c.a}/${c.h}</span></div><div class="number">${c.p===null?'—':c.p.toFixed(1)}<span class="muted" style="font-size:18px">%</span></div><div class="bar"><i style="width:${c.p||0}%;background:${c.p!==null&&c.p<state.target?'var(--accent)':'var(--green)'}"></i></div><p>${forecast(c)}</p><div class="cardactions"><button class="textbtn" data-edit-subject="${s.id}">Edit / starting counts ↗</button></div></article>`}).join('')}</div><p class="disclaimer">Starting counts are for classes before you began logging here. Avoid counting the same period twice.</p>`;$('#addsubject').onclick=()=>subjectDialog();document.querySelectorAll('[data-edit-subject]').forEach(b=>b.onclick=()=>subjectDialog(b.dataset.editSubject))}
function showDialog(html,fn){modal.innerHTML=html;modal.showModal();modal.querySelector('[data-close]').onclick=()=>modal.close();modal.querySelector('form').onsubmit=fn}
function subjectDialog(id){const s=state.subjects.find(x=>x.id===id)||{name:'',attended:0,held:0};showDialog(`<h2>${id?'Edit subject':'A new subject.'}</h2><form><div class="fields"><label>Subject name<input name="name" required maxlength="80" value="${esc(s.name)}"></label><div class="row"><label>Previously attended<input type="number" name="attended" min="0" max="10000" required value="${s.attended}"></label><label>Previously held<input type="number" name="held" min="0" max="10000" required value="${s.held}"></label></div><small>Use counts from before your first app entry. Logged classes are added separately.</small></div><p id="error" class="field-error" role="alert"></p><div class="actions"><button type="button" class="textbtn" data-close>Cancel</button><button type="submit" class="primary">Save subject <span>→</span></button></div></form>`,e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.name=d.name.trim();d.attended=+d.attended;d.held=+d.held;if(!d.name)return;if(d.attended>d.held)return $('#error').textContent='Attended classes cannot exceed held classes.';if(state.subjects.some(x=>x.id!==id&&x.name.toLowerCase()===d.name.toLowerCase()))return $('#error').textContent='A subject with this name already exists.';if(id)Object.assign(s,d);else state.subjects.push({...d,id:uid()});save();modal.close();render();toast('Subject saved.')})}
function renderTimetable(){const slots=state.slots.filter(x=>x.day===day).sort((a,b)=>a.time.localeCompare(b.time));$('#content').innerHTML=`<header class="pagehead"><div><h1>A rhythm for your week.</h1><p class="muted">Add one entry per attendance period, including labs.</p></div><button class="primary" id="addslot">+ Add period</button></header><div class="week" role="group" aria-label="Day of week">${[1,2,3,4,5,6,0].map(d=>`<button data-day="${d}" class="${day===d?'active':''}" aria-pressed="${day===d}">${DAYS[d].slice(0,3)}</button>`).join('')}</div>${slots.length?slots.map(s=>classRow(s,false)).join(''):'<div class="empty"><h3>A clean slate.</h3><p>Add your '+DAYS[day]+' classes to build your weekly routine.</p></div>'}<p class="disclaimer">Timetable periods appear from their start date. Removing a period preserves attendance already recorded for it.</p>`;document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{day=+b.dataset.day;render()});$('#addslot').onclick=()=>sessionDialog(true);document.querySelectorAll('[data-delete-slot]').forEach(b=>b.onclick=()=>{state.slots=state.slots.filter(s=>s.id!==b.dataset.deleteSlot);save();render();toast('Period removed. Existing attendance is preserved.')})}
function sessionDialog(weekly){if(!state.subjects.length)return subjectDialog();showDialog(`<h2>${weekly?'Add a weekly period.':'Add a class.'}</h2><form><div class="fields"><label>Subject<select name="subject">${state.subjects.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label>Start time<input type="time" name="time" value="09:00" required></label>${weekly?`<label>Day<select name="day">${DAYS.map((d,i)=>`<option value="${i}" ${day===i?'selected':''}>${d}</option>`).join('')}</select></label><label>Schedule applies from<input type="date" name="start" required value="${today()}"></label>`:`<small>For ${esc(date)} · This won’t change your weekly timetable.</small>`}</div><p id="error" class="field-error" role="alert"></p><div class="actions"><button class="textbtn" type="button" data-close>Cancel</button><button class="primary" type="submit">Add period <span>→</span></button></div></form>`,e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.id=uid();if(weekly){d.day=+d.day;if(state.slots.some(s=>s.day===d.day&&s.time===d.time))return $('#error').textContent='There’s already a period at this time.';state.slots.push(d)}else{d.date=date;if(sessions().some(s=>s.time===d.time))return $('#error').textContent='There’s already a class at this time.';state.extras.push(d)}save();modal.close();render();toast('Period added.')})}
function renderSettings(){$('#content').innerHTML=`<header class="pagehead"><div><h1>Your corner.</h1><p class="muted">A few details that make this yours.</p></div></header><div class="settings"><form id="settingsform">${profileFields(state.profile)}<label style="margin-top:20px">Attendance target (%)<input name="target" type="number" min="50" max="99" required value="${state.target}"><small>Confirm your minimum requirement with your department. This is a planning target.</small></label><div class="actions"><button class="primary" type="submit">Save changes <span>→</span></button></div></form><hr><h3>Your records, with you.</h3><p class="muted" style="font-size:13px;line-height:1.7">Your data is saved in this browser, on this device. Export a backup before switching browsers or clearing browsing data.</p><div class="actions"><button class="textbtn" id="export">Export backup ↓</button><button class="textbtn" id="import">Restore backup ↑</button><input type="file" id="file" accept="application/json" hidden></div><p class="disclaimer">Present is an independent personal tracker, not an official CUSAT attendance record. No portal connection or cloud sync is enabled.</p></div>`;$('#settingsform').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));state.target=+d.target;delete d.target;if(!d.name.trim()||!d.department.trim()||!d.college.trim())return;state.profile=d;save();render();toast('Your profile is up to date.')};$('#export').onclick=()=>{const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=u;a.download='present-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error();const d=JSON.parse(await f.text());if(!validBackup(d))throw Error();showDialog('<h2>Restore this backup?</h2><form><p class="muted">This replaces the attendance and profile currently saved on this device.</p><div class="actions"><button type="button" class="textbtn" data-close>Cancel</button><button type="submit" class="primary">Restore backup →</button></div></form>',ev=>{ev.preventDefault();state=d;save();modal.close();render();toast('Backup restored.')})}catch{toast('This isn’t a valid Present backup.')}}}
function validBackup(d){const str=x=>typeof x==='string';return d&&d.profile&&['name','college','programme','department','year','semester'].every(k=>str(d.profile[k]))&&Number.isFinite(d.target)&&d.target>=50&&d.target<=99&&Array.isArray(d.subjects)&&d.subjects.every(s=>str(s.id)&&str(s.name)&&Number.isInteger(s.attended)&&Number.isInteger(s.held)&&s.attended>=0&&s.held>=s.attended)&&Array.isArray(d.slots)&&d.slots.every(s=>str(s.id)&&str(s.subject)&&str(s.time)&&str(s.start)&&Number.isInteger(s.day)&&s.day>=0&&s.day<=6)&&Array.isArray(d.extras)&&d.extras.every(s=>str(s.id)&&str(s.subject)&&str(s.time)&&str(s.date))&&d.records&&typeof d.records==='object'&&!Array.isArray(d.records)&&Object.values(d.records).every(r=>r&&str(r.subject)&&str(r.date)&&['present','absent','cancelled'].includes(r.status))}
render();
